create table if not exists public.corporate_ad_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,company_name text not null,contact_name text not null,contact_email text not null,contact_phone text,ad_title text not null,ad_description text,destination_url text,placement text not null check(placement in('listing_feed','homepage','top_banner','multi_placement')),plan text not null check(plan in('starter','business','premium','enterprise')),duration_days integer not null check(duration_days in(7,15,21,30)),amount_dzd numeric(12,2) not null check(amount_dzd>0),creative_url text,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled','paid','active','completed')),review_note text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.corporate_ad_campaigns(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.corporate_ad_requests(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,placement text not null check(placement in('listing_feed','homepage','top_banner','multi_placement')),starts_at timestamptz,ends_at timestamptz,status text not null default 'scheduled' check(status in('scheduled','active','paused','completed','cancelled')),impressions bigint not null default 0,clicks bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.corporate_ad_payments(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.corporate_ad_requests(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,amount_dzd numeric(12,2) not null check(amount_dzd>0),currency text not null default 'DZD' check(currency='DZD'),payment_provider text not null check(payment_provider in('chargily','satim','manual')),payment_method text check(payment_method in('cib','edahabia','qr','cash','other','chargily_app')),provider_transaction_id text,provider_reference text,provider_event_id text,provider_checkout_id text,checkout_creation_token uuid,checkout_creation_started_at timestamptz,status text not null default 'pending' check(status in('pending','paid','failed','cancelled','refunded')),paid_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.corporate_ad_plans(plan text primary key check(plan in('starter','business','premium','enterprise')),duration_days integer not null,base_amount_dzd numeric(12,2) not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.corporate_ad_plans(plan,duration_days,base_amount_dzd) values('starter',7,5000),('business',15,9000),('premium',21,12000),('enterprise',30,15000) on conflict(plan) do update set duration_days=excluded.duration_days,base_amount_dzd=excluded.base_amount_dzd,active=true,updated_at=now();
create unique index if not exists corporate_ad_payments_one_live_per_request_idx on public.corporate_ad_payments(request_id) where status in('pending','paid');
create unique index if not exists corporate_ad_payments_provider_event_uidx on public.corporate_ad_payments(provider_event_id) where provider_event_id is not null;
create unique index if not exists corporate_ad_payments_provider_checkout_uidx on public.corporate_ad_payments(provider_checkout_id) where provider_checkout_id is not null;
create unique index if not exists corporate_ad_payments_creation_token_uidx on public.corporate_ad_payments(checkout_creation_token) where checkout_creation_token is not null;
create index if not exists corporate_ad_requests_user_idx on public.corporate_ad_requests(user_id,created_at desc);
create index if not exists corporate_ad_requests_status_idx on public.corporate_ad_requests(status,created_at desc);
create index if not exists corporate_ad_campaigns_active_idx on public.corporate_ad_campaigns(status,starts_at,ends_at);
create index if not exists corporate_ad_payments_request_idx on public.corporate_ad_payments(request_id,created_at desc);
alter table public.corporate_ad_requests enable row level security;alter table public.corporate_ad_campaigns enable row level security;alter table public.corporate_ad_payments enable row level security;alter table public.corporate_ad_plans enable row level security;
create policy corporate_ad_requests_select_own on public.corporate_ad_requests for select to authenticated using(user_id=auth.uid());create policy corporate_ad_campaigns_select_own on public.corporate_ad_campaigns for select to authenticated using(user_id=auth.uid());create policy corporate_ad_payments_select_own on public.corporate_ad_payments for select to authenticated using(user_id=auth.uid());create policy corporate_ad_plans_read_active on public.corporate_ad_plans for select to authenticated using(active=true);
revoke all on public.corporate_ad_requests from anon,authenticated;grant select on public.corporate_ad_requests to authenticated;revoke all on public.corporate_ad_campaigns from anon,authenticated;grant select on public.corporate_ad_campaigns to authenticated;revoke all on public.corporate_ad_payments from anon,authenticated;grant select on public.corporate_ad_payments to authenticated;revoke all on public.corporate_ad_plans from anon,authenticated;grant select on public.corporate_ad_plans to authenticated;
create or replace function public.create_corporate_ad_request(p_company_name text,p_contact_name text,p_contact_email text,p_contact_phone text,p_ad_title text,p_ad_description text,p_destination_url text,p_placement text,p_plan text,p_creative_url text) returns public.corporate_ad_requests language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();pl public.corporate_ad_plans%rowtype;r public.corporate_ad_requests;mult numeric:=case p_placement when 'homepage' then 2 when 'top_banner' then 1.5 when 'multi_placement' then 2.5 else 1 end;begin if u is null then raise exception 'not_authenticated';end if;if p_placement not in('listing_feed','homepage','top_banner','multi_placement') then raise exception 'invalid_placement';end if;select * into pl from public.corporate_ad_plans where plan=p_plan and active=true;if not found then raise exception 'invalid_plan';end if;insert into public.corporate_ad_requests(user_id,company_name,contact_name,contact_email,contact_phone,ad_title,ad_description,destination_url,placement,plan,duration_days,amount_dzd,creative_url) values(u,trim(p_company_name),trim(p_contact_name),lower(trim(p_contact_email)),nullif(trim(p_contact_phone),''),trim(p_ad_title),nullif(trim(p_ad_description),''),nullif(trim(p_destination_url),''),p_placement,p_plan,pl.duration_days,pl.base_amount_dzd*mult,nullif(trim(p_creative_url),'')) returning * into r;return r;end$$;
create or replace function public.admin_list_corporate_ad_requests(p_status text default null) returns setof public.corporate_ad_requests language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'not_admin';end if;return query select r.* from public.corporate_ad_requests r where p_status is null or r.status=p_status order by r.created_at desc;end$$;
create or replace function public.admin_review_corporate_ad_request(p_request_id uuid,p_status text,p_review_note text default null) returns public.corporate_ad_requests language plpgsql security definer set search_path=public as $$declare r public.corporate_ad_requests;begin if not public.is_admin() then raise exception 'not_admin';end if;if p_status not in('approved','rejected','cancelled') then raise exception 'invalid_review_status';end if;update public.corporate_ad_requests set status=p_status,review_note=nullif(trim(p_review_note),''),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id and status='pending' returning * into r;if not found then raise exception 'request_not_pending';end if;return r;end$$;
create or replace function public.admin_create_corporate_ad_payment(p_request_id uuid,p_provider text,p_method text default null) returns public.corporate_ad_payments language plpgsql security definer set search_path=public as $$declare r public.corporate_ad_requests;p public.corporate_ad_payments;begin if not public.is_admin() then raise exception 'not_admin';end if;select * into r from public.corporate_ad_requests where id=p_request_id;if not found then raise exception 'request_not_found';end if;if r.status<>'approved' then raise exception 'request_not_approved';end if;if p_provider not in('chargily','satim','manual') then raise exception 'invalid_provider';end if;if p_method is not null and p_method not in('cib','edahabia','qr','cash','other','chargily_app') then raise exception 'invalid_payment_method';end if;insert into public.corporate_ad_payments(request_id,user_id,amount_dzd,payment_provider,payment_method) values(r.id,r.user_id,r.amount_dzd,p_provider,p_method) returning * into p;return p;exception when unique_violation then raise exception 'payment_already_exists';end$$;
create or replace function public.prepare_chargily_checkout(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();r public.corporate_ad_requests;p public.corporate_ad_payments;t uuid;begin if u is null then raise exception 'not_authenticated';end if;select * into r from public.corporate_ad_requests where id=p_request_id and user_id=u for update;if not found then raise exception 'request_not_found';end if;if r.status<>'approved' then raise exception 'request_not_approved';end if;select * into p from public.corporate_ad_payments where request_id=r.id and user_id=u and payment_provider='chargily' and status='pending' order by created_at desc limit 1 for update;if not found then raise exception 'pending_chargily_payment_not_found';end if;if p.provider_checkout_id is not null then return jsonb_build_object('status','already_created','payment_id',p.id,'checkout_id',p.provider_checkout_id);end if;if p.checkout_creation_started_at is not null and p.checkout_creation_started_at>now()-interval '10 minutes' then raise exception 'checkout_creation_in_progress';end if;t:=gen_random_uuid();update public.corporate_ad_payments set checkout_creation_token=t,checkout_creation_started_at=now() where id=p.id;return jsonb_build_object('status','ready','payment_id',p.id,'request_id',r.id,'amount_dzd',p.amount_dzd,'currency',lower(p.currency),'payment_method',case when p.payment_method in('edahabia','cib','chargily_app') then p.payment_method else null end,'creation_token',t);end$$;
create or replace function public.bind_chargily_checkout(p_payment_id uuid,p_creation_token uuid,p_checkout_id text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.corporate_ad_payments;u uuid:=auth.uid();begin if u is null then raise exception 'not_authenticated';end if;update public.corporate_ad_payments set provider_checkout_id=trim(p_checkout_id),checkout_creation_token=null,checkout_creation_started_at=null where id=p_payment_id and user_id=u and payment_provider='chargily' and status='pending' and checkout_creation_token=p_creation_token returning * into p;if not found then raise exception 'checkout_binding_failed';end if;return jsonb_build_object('status','bound','payment_id',p.id,'checkout_id',p.provider_checkout_id);exception when unique_violation then raise exception 'checkout_id_already_bound';end$$;
create or replace function public.admin_confirm_corporate_ad_payment(p_payment_id uuid,p_provider_transaction_id text default null,p_provider_reference text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.corporate_ad_payments;r public.corporate_ad_requests;c public.corporate_ad_campaigns;begin if not public.is_admin() then raise exception 'not_admin';end if;select * into p from public.corporate_ad_payments where id=p_payment_id for update;if not found then raise exception 'payment_not_found';end if;if p.status<>'pending' then raise exception 'invalid_payment_state';end if;if p.payment_provider<>'manual' then raise exception 'provider_payment_requires_webhook_verification';end if;select * into r from public.corporate_ad_requests where id=p.request_id for update;if not found or r.status<>'approved' then raise exception 'request_not_approved';end if;update public.corporate_ad_payments set status='paid',paid_at=now(),provider_transaction_id=nullif(trim(p_provider_transaction_id),''),provider_reference=nullif(trim(p_provider_reference),'') where id=p.id;insert into public.corporate_ad_campaigns(request_id,user_id,placement,starts_at,ends_at,status) values(r.id,r.user_id,r.placement,now(),now()+make_interval(days=>r.duration_days),'active') on conflict(request_id) do update set status='active',starts_at=excluded.starts_at,ends_at=excluded.ends_at,updated_at=now() returning * into c;update public.corporate_ad_requests set status='active',updated_at=now() where id=r.id;return jsonb_build_object('payment_id',p.id,'request_id',r.id,'campaign_id',c.id,'status','active');end$$;
create or replace function public.process_chargily_checkout_paid(p_event_id text,p_checkout_id text,p_request_id uuid,p_amount numeric,p_currency text,p_payment_method text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.corporate_ad_payments;r public.corporate_ad_requests;c public.corporate_ad_campaigns;begin if nullif(trim(p_event_id),'') is null then raise exception 'event_id_required';end if;if nullif(trim(p_checkout_id),'') is null then raise exception 'checkout_id_required';end if;if lower(trim(p_currency))<>'dzd' then raise exception 'invalid_currency';end if;if p_amount is null or p_amount<=0 then raise exception 'invalid_amount';end if;select * into p from public.corporate_ad_payments where provider_event_id=p_event_id or provider_checkout_id=trim(p_checkout_id) order by case when provider_event_id=p_event_id then 0 else 1 end limit 1 for update;if not found then raise exception 'checkout_not_bound';end if;if p.payment_provider<>'chargily' then raise exception 'invalid_payment_provider';end if;if p.provider_checkout_id<>trim(p_checkout_id) then raise exception 'checkout_mismatch';end if;if p.request_id<>p_request_id then raise exception 'request_mismatch';end if;if p.currency<>upper(trim(p_currency)) then raise exception 'currency_mismatch';end if;if p.amount_dzd<>p_amount then raise exception 'amount_mismatch';end if;if p.status='paid' then return jsonb_build_object('status','already_paid','payment_id',p.id,'request_id',p.request_id);end if;if p.status<>'pending' then raise exception 'invalid_payment_state';end if;select * into r from public.corporate_ad_requests where id=p.request_id for update;if not found or r.status<>'approved' then raise exception 'request_not_approved';end if;if r.amount_dzd<>p.amount_dzd then raise exception 'request_amount_mismatch';end if;update public.corporate_ad_payments set status='paid',paid_at=now(),provider_transaction_id=coalesce(provider_transaction_id,trim(p_checkout_id)),provider_event_id=p_event_id,payment_method=coalesce(p_payment_method,payment_method) where id=p.id;insert into public.corporate_ad_campaigns(request_id,user_id,placement,starts_at,ends_at,status) values(r.id,r.user_id,r.placement,now(),now()+make_interval(days=>r.duration_days),'active') on conflict(request_id) do update set status='active',starts_at=excluded.starts_at,ends_at=excluded.ends_at,updated_at=now() returning * into c;update public.corporate_ad_requests set status='active',updated_at=now() where id=r.id;return jsonb_build_object('status','active','payment_id',p.id,'request_id',r.id,'campaign_id',c.id);end$$;
revoke all on function public.create_corporate_ad_request(text,text,text,text,text,text,text,text,text,text) from public,anon;grant execute on function public.create_corporate_ad_request(text,text,text,text,text,text,text,text,text,text) to authenticated;
revoke all on function public.admin_list_corporate_ad_requests(text) from public,anon,authenticated;grant execute on function public.admin_list_corporate_ad_requests(text) to authenticated;
revoke all on function public.admin_review_corporate_ad_request(uuid,text,text) from public,anon,authenticated;grant execute on function public.admin_review_corporate_ad_request(uuid,text,text) to authenticated;
revoke all on function public.admin_create_corporate_ad_payment(uuid,text,text) from public,anon,authenticated;grant execute on function public.admin_create_corporate_ad_payment(uuid,text,text) to authenticated;
revoke all on function public.prepare_chargily_checkout(uuid) from public,anon;grant execute on function public.prepare_chargily_checkout(uuid) to authenticated;
revoke all on function public.bind_chargily_checkout(uuid,uuid,text) from public,anon;grant execute on function public.bind_chargily_checkout(uuid,uuid,text) to authenticated;
revoke all on function public.admin_confirm_corporate_ad_payment(uuid,text,text) from public,anon,authenticated;grant execute on function public.admin_confirm_corporate_ad_payment(uuid,text,text) to authenticated;
revoke all on function public.process_chargily_checkout_paid(text,text,uuid,numeric,text,text) from public,anon,authenticated;grant execute on function public.process_chargily_checkout_paid(text,text,uuid,numeric,text,text) to service_role;
